import React, { useState } from 'react';
import { Download, Share2 } from 'lucide-react';

interface GeneratedImageProps {
  dataUrl?: string;
  imageUrl?: string;
  onDownload?: () => void;
  isLoading: boolean;
  appStep: number;
}

const dataURLtoFile = (dataurl: string, filename: string): File => {
  if (!dataurl) {
    throw new Error('dataurl is missing');
  }
  const arr = dataurl.split(',');
  const mime = arr[0].match(/:(.*?);/)![1];
  const bstr = atob(arr[1]);
  let n = bstr.length;
  const u8arr = new Uint8Array(n);
  while (n--) {
    u8arr[n] = bstr.charCodeAt(n);
  }
  return new File([u8arr], filename, { type: mime });
};

const GeneratedImage: React.FC<GeneratedImageProps> = ({
  dataUrl,
  imageUrl,
  onDownload,
  isLoading,
  appStep,
}) => {
  const [isSharing, setIsSharing] = useState(false);

  const handleShare = async () => {
    if (isLoading || !dataUrl) {
      return;
    }

    try {
      setIsSharing(true);
      const file = dataURLtoFile(dataUrl, 'generated_image.png');
      await navigator.share({
        files: [file],
      });
      console.log('Successfully shared');
    } catch (error) {
      console.error('Error sharing:', error);
      if (error instanceof Error && error.name === 'AbortError') {
        // User cancelled the share
        console.log('Share cancelled by user');
      } else {
        alert('Failed to share the image. Please try downloading it instead.');
        if (onDownload) {
          onDownload();
        }
      }
    } finally {
      setIsSharing(false);
    }
  };

  const handleDownload = () => {
    if (!dataUrl) {
      return;
    }
    const link = document.createElement('a');
    link.href = dataUrl;
    link.download = 'generated_image.png';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  if (!imageUrl && !dataUrl) {
    return (
      <div className="flex w-full items-center justify-center p-4">
        Generating Image...
      </div>
    );
  }

  return (
    <div className="relative">
      {appStep === 2 && (
        <div className="absolute top-2 right-2 flex space-x-2">
          <button
            onClick={handleDownload}
            disabled={isLoading}
            className={`rounded-md border p-2 ${
              isLoading ? 'opacity-50 cursor-not-allowed' : ''
            }`}
          >
            <Download size={20} />
          </button>
          <button
            onClick={handleShare}
            disabled={isLoading || isSharing}
            className={`rounded-md border p-2 ${
              isLoading || isSharing ? 'opacity-50 cursor-not-allowed' : ''
            }`}
          >
            <Share2 size={20} />
          </button>
        </div>
      )}
      <img
        src={imageUrl || dataUrl}
        alt="generated image"
